-- THE HUB: run in your Supabase project's SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, username text not null unique check (username ~ '^[a-z0-9_]{3,24}$'), display_name text not null check (length(display_name) between 1 and 80), bio text not null default '', created_at timestamptz not null default now());
create table if not exists public.posts (id uuid primary key default gen_random_uuid(), author_id uuid not null references public.profiles(id) on delete cascade, body text not null default '' check(length(body)<=3000), media_path text, media_type text check(media_type in ('image','video')), created_at timestamptz not null default now(), check(length(trim(body))>0 or media_path is not null));
create table if not exists public.comments (id uuid primary key default gen_random_uuid(), post_id uuid not null references public.posts(id) on delete cascade, author_id uuid not null references public.profiles(id) on delete cascade, body text not null check(length(trim(body)) between 1 and 1000), created_at timestamptz not null default now());
create table if not exists public.likes (post_id uuid not null references public.posts(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, primary key(post_id,user_id));
create table if not exists public.rooms (id uuid primary key default gen_random_uuid(), name text not null check(length(trim(name)) between 3 and 80), description text not null default '', owner_id uuid not null references public.profiles(id), created_at timestamptz not null default now());
create table if not exists public.room_messages (id uuid primary key default gen_random_uuid(), room_id uuid not null references public.rooms(id) on delete cascade, author_id uuid not null references public.profiles(id) on delete cascade, body text not null check(length(trim(body)) between 1 and 2000), created_at timestamptz not null default now());
create table if not exists public.conversations (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now());
create table if not exists public.conversation_members (conversation_id uuid not null references public.conversations(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, primary key(conversation_id,user_id));
create table if not exists public.direct_messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id) on delete cascade, author_id uuid not null references public.profiles(id) on delete cascade, body text not null check(length(trim(body)) between 1 and 2000), created_at timestamptz not null default now());
create table if not exists public.reports (id uuid primary key default gen_random_uuid(), reporter_id uuid not null references public.profiles(id), post_id uuid references public.posts(id), message_id uuid references public.room_messages(id), reason text not null check(length(trim(reason)) between 3 and 500), created_at timestamptz not null default now(), check ((post_id is not null)::int + (message_id is not null)::int = 1));
create index if not exists posts_recent on public.posts(created_at desc);
create index if not exists comments_by_post on public.comments(post_id,created_at);
create index if not exists room_messages_recent on public.room_messages(room_id,created_at desc);
create index if not exists direct_messages_recent on public.direct_messages(conversation_id,created_at desc);
create index if not exists members_by_user on public.conversation_members(user_id);
create or replace function public.on_user_signup() returns trigger language plpgsql security definer set search_path=public as $$
begin
 insert into public.profiles(id,username,display_name) values(new.id,'user_'||substr(replace(new.id::text,'-',''),1,16),coalesce(nullif(left(new.raw_user_meta_data->>'display_name',80),''),'New member'));
 return new;
end;$$;
drop trigger if exists create_profile_on_signup on auth.users;
create trigger create_profile_on_signup after insert on auth.users for each row execute function public.on_user_signup();
create or replace function public.is_conversation_member(cid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.conversation_members where conversation_id=cid and user_id=auth.uid()) $$;
create or replace function public.start_dm(other_user uuid) returns uuid language plpgsql security definer set search_path=public as $$
declare cid uuid;
begin
 if auth.uid() is null or other_user=auth.uid() or not exists(select 1 from public.profiles where id=other_user) then raise exception 'Invalid recipient'; end if;
 select cm1.conversation_id into cid from public.conversation_members cm1 join public.conversation_members cm2 on cm2.conversation_id=cm1.conversation_id and cm2.user_id=other_user where cm1.user_id=auth.uid() and (select count(*) from public.conversation_members cm3 where cm3.conversation_id=cm1.conversation_id)=2 limit 1;
 if cid is null then insert into public.conversations default values returning id into cid; insert into public.conversation_members(conversation_id,user_id) values(cid,auth.uid()),(cid,other_user); end if;
 return cid;
end;$$;
revoke all on function public.start_dm(uuid) from public; grant execute on function public.start_dm(uuid) to authenticated;
revoke all on function public.is_conversation_member(uuid) from public; grant execute on function public.is_conversation_member(uuid) to authenticated;
alter table public.profiles enable row level security;
alter table public.posts enable row level security;
alter table public.comments enable row level security;
alter table public.likes enable row level security;
alter table public.rooms enable row level security;
alter table public.room_messages enable row level security;
alter table public.conversations enable row level security;
alter table public.conversation_members enable row level security;
alter table public.direct_messages enable row level security;
alter table public.reports enable row level security;
create policy "profiles read" on public.profiles for select to authenticated using(true);
create policy "profiles edit own" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "posts read" on public.posts for select to authenticated using(true);
create policy "posts add" on public.posts for insert to authenticated with check(author_id=auth.uid() and (media_path is null or media_path like auth.uid()::text||'/%'));
create policy "posts delete own" on public.posts for delete to authenticated using(author_id=auth.uid());
create policy "comments read" on public.comments for select to authenticated using(true);
create policy "comments add" on public.comments for insert to authenticated with check(author_id=auth.uid());
create policy "comments delete own" on public.comments for delete to authenticated using(author_id=auth.uid());
create policy "likes read" on public.likes for select to authenticated using(true);
create policy "likes add" on public.likes for insert to authenticated with check(user_id=auth.uid());
create policy "likes remove" on public.likes for delete to authenticated using(user_id=auth.uid());
create policy "rooms read" on public.rooms for select to authenticated using(true);
create policy "rooms add" on public.rooms for insert to authenticated with check(owner_id=auth.uid());
create policy "rooms delete own" on public.rooms for delete to authenticated using(owner_id=auth.uid());
create policy "room messages read" on public.room_messages for select to authenticated using(true);
create policy "room messages add" on public.room_messages for insert to authenticated with check(author_id=auth.uid());
create policy "room messages delete own" on public.room_messages for delete to authenticated using(author_id=auth.uid());
create policy "conversations read members" on public.conversations for select to authenticated using(public.is_conversation_member(id));
create policy "members read members" on public.conversation_members for select to authenticated using(public.is_conversation_member(conversation_id));
create policy "dm read members" on public.direct_messages for select to authenticated using(public.is_conversation_member(conversation_id));
create policy "dm send members" on public.direct_messages for insert to authenticated with check(author_id=auth.uid() and public.is_conversation_member(conversation_id));
create policy "reports own" on public.reports for insert to authenticated with check(reporter_id=auth.uid());
create policy "reports read own" on public.reports for select to authenticated using(reporter_id=auth.uid());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('hub-media','hub-media',true,52428800,array['image/jpeg','image/png','image/webp','image/gif','video/mp4','video/webm','video/quicktime']) on conflict(id) do update set public=true,file_size_limit=52428800,allowed_mime_types=excluded.allowed_mime_types;
create policy "hub media view" on storage.objects for select to authenticated using(bucket_id='hub-media');
create policy "hub media upload own folder" on storage.objects for insert to authenticated with check(bucket_id='hub-media' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "hub media delete own folder" on storage.objects for delete to authenticated using(bucket_id='hub-media' and (storage.foldername(name))[1]=auth.uid()::text);
do $$ begin alter publication supabase_realtime add table public.posts; exception when duplicate_object then null; end $$;
do $$ begin alter publication supabase_realtime add table public.room_messages; exception when duplicate_object then null; end $$;
do $$ begin alter publication supabase_realtime add table public.direct_messages; exception when duplicate_object then null; end $$;